patch:
diff --git a/repro/no-loss-of-precision-19957.js b/repro/no-loss-of-precision-19957.js
new file mode 100644
index 0000000..ebdf3c7
--- /dev/null
+++ b/repro/no-loss-of-precision-19957.js
@@ -0,0 +1,57 @@
+/**
+ * Reproduction: no-loss-of-precision falsely flags exactly-representable
+ * literals like `9.000e+3` (eslint/eslint#19957).
+ *
+ * Run from the repo root: node repro/no-loss-of-precision-19957.js
+ * Exits 1 while the bug is present.
+ */
+"use strict";
+
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+
+// All of these are exactly representable integers, so none should be reported.
+const cases = [
+	"9.000e+3", // from the report
+	"9.000e3", // from the triage comment
+	"9.0000e4", // from the triage comment
+	"9.000e4", // control: currently not reported
+	"9.0000e5", // control: currently not reported
+	"9.000", // control
+	"9000", // control
+	"1.0e1",
+	"1.00e2",
+	"1.50e2",
+	"12.30e1",
+];
+
+let falsePositives = 0;
+
+for (const code of cases) {
+	const messages = linter.verify(`const x = ${code};`, {
+		rules: { "no-loss-of-precision": "error" },
+	});
+	const flagged = messages.some(m => m.ruleId === "no-loss-of-precision");
+	const value = Number(code);
+	// The rule compares the raw literal against value.toPrecision(<raw significant digits>).
+	const digits = code.split(/e/iu)[0].replace(".", "").replace(/^0+/u, "")
+		.length;
+
+	if (flagged) {
+		falsePositives++;
+	}
+	console.log(
+		`${flagged ? "FLAGGED" : "ok     "}  ${code.padEnd(10)} value=${String(value).padEnd(6)} toPrecision(${digits})=${value.toPrecision(digits)}`,
+	);
+	for (const m of messages) {
+		if (m.ruleId !== "no-loss-of-precision") {
+			console.log(`         unexpected message: ${m.message}`);
+		}
+	}
+}
+
+console.log(
+	`\n${falsePositives} false positive(s) from no-loss-of-precision (expected 0).`,
+);
+process.exitCode = falsePositives ? 1 : 0;
